=IF(
  ISBLANK([_THISROW].[วันที่]),
  "",
  IF(
    ISNOTBLANK(
      ANY(
        SELECT(
          PriceOverride[UsePriceDate],
          AND(
            [StartDate] <= [_THISROW].[วันที่],
            [EndDate] >= [_THISROW].[วันที่],
            [JobName] = [_THISROW].[ชื่องาน]
          )
        )
      )
    ),
    ANY(
      SELECT(
        ราคาน้ำมันดีเซล[ราคา/หน่วย],
        [วันที่] =
          ANY(
            SELECT(
              PriceOverride[UsePriceDate],
              AND(
                [StartDate] <= [_THISROW].[วันที่],
                [EndDate] >= [_THISROW].[วันที่],
                [JobName] = [_THISROW].[ชื่องาน]
              )
            )
          )
      )
    ),

    IF(
      ISNOTBLANK(
        ANY(
          SELECT(
            PriceOverride[UsePriceDate],
            AND(
              [StartDate] <= [_THISROW].[วันที่],
              [EndDate] >= [_THISROW].[วันที่],
              ISBLANK([JobName]) 
            )
          )
        )
      ),
      ANY(
        SELECT(
          ราคาน้ำมันดีเซล[ราคา/หน่วย],
          [วันที่] =
            ANY(
              SELECT(
                PriceOverride[UsePriceDate],
                AND(
                  [StartDate] <= [_THISROW].[วันที่],
                  [EndDate] >= [_THISROW].[วันที่],
                  ISBLANK([JobName]) 
                )
              )
            )
        )
      ),
      ANY(
        SELECT(
          ราคาน้ำมันดีเซล[ราคา/หน่วย],
          [วันที่] =
            DATE(
              CONCATENATE(
                YEAR(EOMONTH([_THISROW].[วันที่], -1)),
                "-",
                RIGHT("0" & MONTH(EOMONTH([_THISROW].[วันที่], -1)), 2),
                "-25"
              )
            )
        )
      )
    )
  )
)

